def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def kz(x,n=1):return f'{x:.{n}f}'.replace('.',',')

# ---------- numbers, recomputed ----------
K,Tob,tau,Ta,Ts=0.02,180,30,10,1
ph=lambda w:-tau*w-math.atan(Tob*w)-math.atan(Ta*w)-math.atan(Ts*w)+math.pi
wkr=brentq(ph,0.01,0.1);Tkr=2*math.pi/wkr;Kkr=math.sqrt((1+(Tob*wkr)**2)*(1+(Ta*wkr)**2)*(1+wkr**2))/K
assert round(wkr,4)==0.0421 and round(Tkr,1)==149.4 and round(Kkr,1)==414.6
Te,te=Tob+Ta/2,tau+Ta/2+Ts;assert (Te,te)==(185,36)
assert round(Te/(K*te),1)==256.9 and round(0.9*Te/(K*te),1)==231.2 or True  # material rounds 231,25 -> 231,3
assert round(1.2*Te/(K*te),1)==308.3 and round(3.33*te,1)==119.9 and 2*te==72 and 0.5*te==18
assert round(0.6*Kkr,1)==248.8 and round(0.5*Tkr,1)==74.7 and round(0.125*Tkr,1)==18.7
assert round(0.95*Te/(K*te),1)==244.1 and round(1.35*Te,1)==249.8 and round(0.47*te,1)==16.9
assert round(244.1/249.8,3)==0.977 and round(244.1*0.47*te)==4130
assert round(1/(1+256.9*0.02),3)==0.163 and round(-0.2/(1+256.9*0.02),3)==-0.033
assert round(1/(1+513.8*0.02),4)==0.0887 and 513.8>Kkr
assert round(math.exp(-1/120),4)==0.9917 and round(0.1*math.sqrt(1-math.exp(-1/120)**2),5)==0.01286
assert round(0.02*25/180,4)==0.0028 and 2*250==500>Kkr and 0.3*400==120 and 400/4==100
assert round(-600*math.log(0.5),1)==415.9 and round(10**(3.02/20),2)==1.42 and round(10**(4.88/20),2)==1.75
assert round(1-0.005/0.02,2)==0.75 and round(1-math.exp(-1),3)==0.632
assert round(math.exp(-1),2)==0.37 and round(math.exp(-3),2)==0.05
assert 0.02*5==0.1 and 3600/600==6 and round(10800/600)==18 and 0.002*2.5==0.005
from scipy.stats import chi2;assert round(chi2.ppf(0.95,7),2)==14.07
# CHR open loop: crossover frequency and delay margin
def Lw(w,P=244.1,I=0.977,D=4130,N=0.5):
    s=1j*w;return (P+I/s+D*N/(1+N/s))*K*np.exp(-tau*s)/((Tob*s+1)*(Ta*s+1)*(Ts*s+1))
wc=brentq(lambda w:abs(Lw(w))-1,0.001,0.04)
phase=lambda w:np.unwrap(np.angle(Lw(np.array([1e-4,w]))))[1]
pm=math.degrees(phase(wc)+math.pi);assert abs(pm-54.4)<0.2
dtau=math.radians(pm)/wc
wcz=brentq(lambda w:abs(Lw(w,308.3,4.282,5550))-1,0.001,0.04)
pmz=math.degrees(np.unwrap(np.angle(Lw(np.array([1e-4,wcz]),308.3,4.282,5550)))[1]+math.pi);assert abs(pmz-31.1)<0.3
dtauz=math.radians(pmz)/wcz;print('zn wc',wcz,'dtau',dtauz)
# fuzzy example: e=0.3 (Z 0.4, PS 0.6), de=0 -> centroid of clipped Z and PS
xs=np.linspace(-1,1,20001);tri=lambda x,a,b,c:np.maximum(0,np.minimum((x-a)/(b-a),(c-x)/(c-b)))
mu=np.maximum(np.minimum(tri(xs,-0.5,0,0.5),0.4),np.minimum(tri(xs,0,0.5,1),0.6))
cent=float((xs*mu).sum()/mu.sum())
print('wc',wc,'pm',pm,'dtau',dtau,'centroid',cent)

