def qualfig():
    z,wn=0.4,0.03;wd=wn*math.sqrt(1-z*z)
    yf=lambda t:1-math.exp(-z*wn*t)*(math.cos(wd*t)+z/math.sqrt(1-z*z)*math.sin(wd*t))
    ts=np.arange(0,600.5,2);ys=[yf(t) for t in ts]
    tr=max(t for t,v in zip(ts,ys) if abs(v-1)>0.05)
    x0,y0=40,180;X=lambda t:x0+t*0.48;Y=lambda v:y0-v*100
    o=A(x0,y0,334,y0)+A(x0,y0,x0,30)+TL(310,196,'t','t-s')+TL(46,34,'y','t-s')
    o+='<path d="M'+' L'.join(f'{X(t):.1f} {Y(v):.1f}' for t,v in zip(ts,ys))+'" class="lna"/>'
    for v in (0.95,1.05):o+=f'<line x1="{x0}" y1="{Y(v):.1f}" x2="334" y2="{Y(v):.1f}" class="ln dash"/>'
    o+=TL(300,Y(1.05)-4,'±5 %','t-s mu')
    ip=int(np.argmax(ys));tp=ts[ip];o+=A(X(tp),Y(1),X(tp),Y(ys[ip])+1,two=True)+TL(X(tp)+10,Y(ys[ip])+2,'A₁ → σ','t-s ac')
    i3=ip+int(np.argmax(ys[ip+60:ip+260]))+60;o+=TL(X(ts[i3])-8,Y(ys[i3])-8,'A₃','t-s ac')
    o+=f'<line x1="{X(tr):.1f}" y1="{Y(0.95):.1f}" x2="{X(tr):.1f}" y2="{y0}" class="ln dash"/>'+T(X(tr),y0+14,'tр','t-s t-b')
    o+=T(170,224,'σ = A₁/yорн·100 %;   ψ = 1 − A₃/A₁','t-s')
    return o,tr
