def bodefig():
    ws=np.logspace(-3,-1,400);Lv=Lw(ws);db=20*np.log10(abs(Lv));phs=np.degrees(np.unwrap(np.angle(Lv)))
    X=lambda w:40+(math.log10(w)+3)/2*290
    Ym=lambda d:22+(30-d)*(78/60)   # +30..-30 dB -> 22..100
    Yp=lambda p:120+(-90-p)*(80/180) # -90..-270 deg -> 120..200
    o=TL(4,30,'дБ','t-s')+TL(4,128,'град','t-s')
    o+=L(40,Ym(0),330,Ym(0),'ln dash')+TR(36,Ym(0)+4,'0','t-s')+L(40,Yp(-180),330,Yp(-180),'ln dash')+TR(36,Yp(-180)+4,'−180°','t-s')
    o+=L(40,20,40,102)+L(40,118,40,202)
    m=[(X(w),Ym(max(-30,min(30,d)))) for w,d in zip(ws,db)];p=[(X(w),Yp(max(-270,min(-90,q)))) for w,q in zip(ws,phs)]
    o+='<path d="M'+' L'.join(f'{x:.1f} {y:.1f}' for x,y in m)+'" class="lna"/>'+'<path d="M'+' L'.join(f'{x:.1f} {y:.1f}' for x,y in p)+'" class="lna"/>'
    i180=int(np.argmin(abs(phs+180)));w180=ws[i180];gm=-db[i180]
    o+=A(X(wc),Yp(-180),X(wc),Yp(phs[int(np.argmin(abs(ws-wc)))])+1)+TL(X(wc)+5,Yp(-160),f'фаза қоры {kz(pm)}°','t-s ac')
    o+=A(X(w180),Ym(0),X(w180),Ym(-gm)-1)+TR(X(w180)-6,Ym(-gm/2)+14,f'амплитуда қоры {kz(gm)} дБ','t-s ac')
    o+=f'<line x1="{X(wc):.1f}" y1="{Ym(0)}" x2="{X(wc):.1f}" y2="{Yp(-180)}" class="ln dash"/>'
    o+=T(185,216,'ω, рад/с (лог. шкала: 0,001 … 0,1)','t-s mu')
    return o,gm
