def mffig():
    X=lambda v:40+(v+1)*130;Y=lambda m:150-m*100
    o=L(30,150,320,150)+''.join(L(X(v),150,X(v),154)+T(X(v),168,kz(v,1) if v not in(-1,0,1) else str(int(v)).replace('-','−'),'t-s') for v in (-1,-0.5,0,0.5,1))
    for i,(nm,c) in enumerate([('NB',-1),('NS',-0.5),('Z',0),('PS',0.5),('PB',1)]):
        a,b2=max(-1,c-0.5),min(1,c+0.5)
