def dfig():
    rng=np.random.default_rng(7);N=3600;a=math.exp(-1/120);b=0.1*math.sqrt(1-a*a)
    d=np.zeros(N)
    for k in range(1,N):d[k]=a*d[k-1]+b*rng.standard_normal()
    jumps=np.zeros(N);t=0.0;ev=[]
    while True:
        t+=-600*math.log(rng.random())
        if t>=N:break
        ev.append(int(t));jumps[int(t):]+=rng.choice([-1,1])*rng.uniform(0.3,0.5)
    D=d+jumps;lo,hi=float(D.min()),float(D.max());pad=0.1
    X=lambda k:40+k/N*290;Y=lambda v:170-(v-lo+pad)/(hi-lo+2*pad)*140
    o=A(40,180,334,180)+A(40,180,40,22)+TL(306,174,'t, с','t-s')+TL(46,26,'ΔD, т/сағ','t-s')
    o+='<path d="M'+' L'.join(f'{X(k):.1f} {Y(D[k]):.1f}' for k in range(0,N,6))+'" class="lna"/>'
    o+=f'<line x1="40" y1="{Y(0):.1f}" x2="330" y2="{Y(0):.1f}" class="ln dash"/>'+TR(36,Y(0)+4,'0','t-s')
    for e in ev:o+=f'<polygon points="{X(e):.1f},180 {X(e)-4:.1f},188 {X(e)+4:.1f},188" class="hda"/>'
    o+=T(40,196,'0','t-s')+T(330,196,'3600','t-s')+T(185,212,f'▲ — тұтынушы оқиғасы ({len(ev)} рет, күтілгені 6)','t-s mu')
    return o
