def histfig():
    rng=np.random.default_rng(3);n=20000
    x=np.where(rng.random(n)<0.85,rng.normal(0,0.010,n),rng.normal(0,0.035,n));s=x.std()
    edges=np.linspace(-0.06,0.06,25);h,_=np.histogram(x,edges,density=True)
    X=lambda v:40+(v+0.06)/0.12*290;top=max(h.max(),1/(s*math.sqrt(2*math.pi)));Y=lambda f:176-f/top*140
    o=L(36,176,334,176)
    for i,v in enumerate(h):o+=f'<rect x="{X(edges[i])+0.5:.1f}" y="{Y(v):.1f}" width="{X(edges[i+1])-X(edges[i])-1:.1f}" height="{176-Y(v):.1f}" class="soft"/>'
    vs=np.linspace(-0.06,0.06,200);g=np.exp(-vs**2/(2*s*s))/(s*math.sqrt(2*math.pi))
    o+='<path d="M'+' L'.join(f'{X(v):.1f} {Y(f):.1f}' for v,f in zip(vs,g))+'" class="lna"/>'
    o+=TL(186,48,'қалыпты заң (сол σ-мен)','t-s ac')+TL(186,64,'бағаналар — гистограмма','t-s')
    o+=T(80,150,'ауыр «құйрық»','t-s')+A(80,156,66,170)+T(X(0),192,'0','t-s')+T(185,212,'ΔP (сапалық мысал, нақты нәтиже емес)','t-s mu')
    return o
